<?php $page=max(1,min(100000,(int)($_GET['page']??1)));$total=(int)$a->db->value("SELECT COUNT(*) FROM cy_threads WHERE mode IN ('question','poll')");$rows=$a->db->all("SELECT t.*,c.title,c.status,c.author_id,(SELECT COUNT(*) FROM cy_poll_votes v WHERE v.content_id=t.content_id) AS votes FROM cy_threads t JOIN cy_contents c ON c.id=t.content_id WHERE t.mode IN ('question','poll') ORDER BY c.id DESC LIMIT 30 OFFSET ?",[($page-1)*30]); ?>
<div class="admin-title"><div><span class="eyebrow">PEOPLE / IDEAS / PERSPECTIVES</span><h1><?= t('Questions and polls') ?></h1><p><?= t('One content system, with approved answers and auditable voting.') ?></p></div><a class="btn" href="<?= e(au('edit_content',['kind'=>'thread'])) ?>"><?= icon('plus') ?><?= t('Start a conversation') ?></a></div>
<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th><?= t('Title') ?></th><th><?= t('Type') ?></th><th><?= t('Status') ?></th><th><?= t('Activity') ?></th><th><?= t('Manage') ?></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><a href="<?= e(url('article',['id'=>$row['content_id']])) ?>"><?= e($row['title']) ?></a></td><td><span class="pill"><?= t($row['mode']) ?></span></td><td><?= t($row['status']) ?></td><td><?= $row['mode']==='poll'?(int)$row['votes'].' '.t('votes'):t((int)$row['accepted_comment_id']?'Accepted answer':'Waiting for an answer') ?></td><td><a class="text-link" href="<?= e(au('edit_content',['id'=>$row['content_id']])) ?>"><?= t('Edit') ?><?= icon('edit') ?></a></td></tr><?php endforeach ?></tbody></table></div><?php if(!$rows){empty_state('Start a conversation','message');} ?><?php partial('pagination',['tab'=>'threads','pagination'=>['page'=>$page,'pages'=>max(1,(int)ceil($total/30))]]); ?></section>
